INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (23, 'Dz Type Condenzer', 'dz-type-condenzer-23', 2, 'Thilhara Genuine', 'TH-70', 'Is an essential component of refrigeration and air conditioning systems, playing a vital role in the heat exchange process that facilitates the cooling of various applications. With its efficient design and high performance, the Fn Type Condenser is trusted for its ability to maintain temperature and ensure the proper functioning of cooling systems.', '{"Application": "Walk-in Chillers, Freezers & Food Storage Facilities", "Refrigerant Compatibility": "R404A / R507 / R22 / R448A", "Casing": "Powder-Coated Anti-Corrosive Heavy Aluminum Alloy", "Defrost Type": "Electric Heating Elements / Air Defrost"}'::jsonb, TRUE, 5.0, 12, '/products/cold-room-accessories/dz_type_condenzer.jpg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (24, 'Cold Room', 'cold-room-24', 2, 'Thilhara Genuine', 'TH-14', 'Boost your cold storage efficiency with our Cold Room Accessories, meticulously designed to optimize your Cold Room''s functionality. Engineered for precision, these accessories create a consistent and controlled environment for perishable goods. From specialized shelving systems to energy-efficient LED lighting, our accessories enhance organization, visibility, and accessibility within your Cold Room. Advanced temperature and humidity control units guarantee perfect storage conditions, preserving freshness. Easy to install and maintain, these accessories are tailored to fit your Cold Room specifications, maximizing space and minimizing energy consumption. Upgrade your cold storage facility with our top-notch accessories, ensuring peak product quality and streamlining your operational processes...', '{"Application": "Walk-in Chillers, Freezers & Food Storage Facilities", "Refrigerant Compatibility": "R404A / R507 / R22 / R448A", "Casing": "Powder-Coated Anti-Corrosive Heavy Aluminum Alloy", "Defrost Type": "Electric Heating Elements / Air Defrost"}'::jsonb, TRUE, 5.0, 12, '/products/cold-room-accessories/cold_room.jpg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (25, 'Cold Room Pannels', 'cold-room-pannels-25', 3, 'Thilhara Genuine', 'TH-13', 'Upgrade your cold storage facility with our Cold Room Accessories, tailored for Cold Room Panels. Engineered for efficiency, these accessories enhance insulation, creating airtight seals between panels for optimal temperature control. Crafted from high-quality materials, they resist extreme temperatures, maintaining a consistent chilled environment. Easy to install, they streamline construction or retrofitting, saving time and labor costs. Precision fit ensures seamless integration, reducing energy consumption and operational expenses. Whether for industrial storage, pharmaceuticals, or food preservation, our Cold Room Panels and accessories offer unparalleled insulation, preserving product integrity. Elevate your cold storage with these high-performance accessories, ensuring reliable temperature regulation and maximizing your goods'' longevity..', '{"Core Material": "High Density Polyurethane Foam (PUR / PIR)", "Density": "40-42 kg/m\u00b3", "Cladding": "Pre-painted Galvanized Steel / Food Grade Coating", "Lock Mechanism": "Cam-Lock System with Air-tight Gaskets"}'::jsonb, TRUE, 5.0, 12, '/products/coldroom-panel-and-door/cold_room_pannels.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (26, 'Cold Room', 'cold-room-26', 3, 'Thilhara Genuine', 'TH-2', 'Elevate your cooling solutions with our Air Condition Accessories for Cold Rooms. Designed for industrial and commercial spaces, these accessories enhance your cold room''s efficiency and ensure optimal performance. Our precision-engineered temperature sensors provide accurate readings, allowing you to maintain the perfect climate for your products. The heavy-duty insulation materials and door seals guarantee minimal heat exchange, reducing energy consumption and operational costs. Additionally, our advanced air filters trap dust and impurities, ensuring clean, refreshing air circulation. The easy-to-install digital thermostats enable precise temperature control, adapting to varying cooling needs seamlessly. With our Air Condition Accessories, your cold room becomes a model of efficiency, preserving your inventory while maximizing energy savings. Experience unparalleled reliability and performance, ensuring your products stay fresh and your energy bills stay low..', '{"Core Material": "High Density Polyurethane Foam (PUR / PIR)", "Density": "40-42 kg/m\u00b3", "Cladding": "Pre-painted Galvanized Steel / Food Grade Coating", "Lock Mechanism": "Cam-Lock System with Air-tight Gaskets"}'::jsonb, TRUE, 5.0, 12, '/products/coldroom-panel-and-door/cold_room.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (27, 'Suction Accumulator', 'suction-accumulator-27', 4, 'Thilhara Genuine', 'TH-57', 'Introducing our Suction Accumulator – essential for efficient refrigeration in cold storage. Engineered for precision, it stabilizes refrigerant flow, preventing liquid entry into the compressor. Crafted from high-quality materials, it ensures durability and reliability under varying temperatures. Effectively separating liquid from gas, it optimizes compressor performance, preventing damage. Easy to install and maintain, it simplifies refrigeration, enhancing equipment efficiency. Trust in its dependable performance to preserve product freshness, reduce component wear, and extend your system''s lifespan...', '{"Max Working Pressure": "33 bar (480 psi)", "Shell Material": "Carbon Steel with Corrosion-Resistant Finish", "Inlet/Outlet Connections": "Rotolock / Sweat ODS", "Standard": "CE / UL / ISO9001 Certified"}'::jsonb, TRUE, 5.0, 12, '/products/reciever/suction_accumulator.jpg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (28, 'Refrigerant Heat Exchanger Suction accumulator', 'refrigerant-heat-exchanger-suction-accumulator-28', 4, 'Thilhara Genuine', 'TH-48', 'Introducing our Refrigerant Heat Exchanger Suction Accumulator – the key to efficient refrigeration systems. Crafted for precision, this accumulator maintains optimal suction pressure and prevents liquid refrigerant from entering the compressor. Made from high-quality materials, it ensures reliable operation in cold storage, enhancing system efficiency. Its heat exchanger design promotes energy efficiency and consistent cooling. Compact and easy to install, it''s essential for commercial freezers and walk-in coolers. Trust in our Suction Accumulator for efficient heat removal, ensuring the longevity of your cold room equipment and preserving product freshness...', '{"Max Working Pressure": "33 bar (480 psi)", "Shell Material": "Carbon Steel with Corrosion-Resistant Finish", "Inlet/Outlet Connections": "Rotolock / Sweat ODS", "Standard": "CE / UL / ISO9001 Certified"}'::jsonb, TRUE, 5.0, 12, '/products/reciever/refrigerant_heat_exchanger_suction_accumulator.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (29, 'Oil Reservoir', 'oil-reservoir-29', 4, 'Thilhara Genuine', 'TH-44', 'Introducing our Oil Reservoir – ensuring efficient lubrication in refrigeration systems. Crafted for precision, it provides constant oil supply to critical components, optimizing performance and longevity. Made from high-quality materials, it withstands extreme temperatures and corrosive environments. Its design prevents overflow and contamination, maintaining system integrity. Easy to install and maintain, it simplifies the lubrication process, saving time and effort. Trust our Oil Reservoir for smooth operation, reduced wear, and prolonged equipment life in cold storage facilities...', '{"Max Working Pressure": "33 bar (480 psi)", "Shell Material": "Carbon Steel with Corrosion-Resistant Finish", "Inlet/Outlet Connections": "Rotolock / Sweat ODS", "Standard": "CE / UL / ISO9001 Certified"}'::jsonb, TRUE, 5.0, 12, '/products/reciever/oil_reservoir.webp') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (30, 'Tee ccc', 'tee-ccc-30', 5, 'Thilhara Genuine', 'TH-58', 'Introducing our Copper Fitting Tee (CCC) – the key to efficient refrigeration systems. Crafted with precision from high-quality copper, this tee ensures seamless connections and optimal refrigerant flow in cold storage setups. Its durable design guarantees corrosion resistance, even in demanding environments. The tee configuration allows easy branching of refrigerant lines, accommodating versatile system setups. Leak-free seals ensure efficient heat exchange, promoting consistent cooling in cold rooms. Easy to install and compatible with various pipe sizes, our Copper Fitting Tee simplifies installations, saving time for technicians. Trust in its quality to enhance your refrigeration system, ensuring uninterrupted cooling and product freshness...', '{"Material": "High Purity Deoxidized Copper (Cu-DHP 99.9%)", "Standard": "ASME B16.22 / EN 1254-1", "Connection": "Sweat / Solder ODS", "Working Pressure": "Up to 45 bar (High Pressure Compatible)"}'::jsonb, TRUE, 5.0, 12, '/products/copper-fitting/tee_ccc.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (31, 'Return Bend cc', 'return-bend-cc-31', 5, 'Thilhara Genuine', 'TH-49', 'Introducing our Return Bend (CC) – the crucial component for efficient refrigerant flow redirection in cold storage systems. Engineered for precision, it ensures seamless cooling circulation, preventing pressure drops and maintaining optimal performance. Made from durable materials, it withstands extreme temperatures, ideal for cold room applications. Its precisely bent design promotes smooth refrigerant flow, ensuring consistent temperatures. Easy to install, it enhances system efficiency, reduces energy consumption, and prolongs equipment life. Trust in its reliability for uninterrupted cooling, maximizing the performance and longevity of your refrigeration systems...', '{"Material": "High Purity Deoxidized Copper (Cu-DHP 99.9%)", "Standard": "ASME B16.22 / EN 1254-1", "Connection": "Sweat / Solder ODS", "Working Pressure": "Up to 45 bar (High Pressure Compatible)"}'::jsonb, TRUE, 5.0, 12, '/products/copper-fitting/return_bend_cc.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (32, 'Fitting Reducer ftg', 'fitting-reducer-ftg-32', 5, 'Thilhara Genuine', 'TH-32', 'Introducing our Cold Room Accessories Copper Fitting Reducer (FTG) – the essential component for seamless and reliable connections in refrigeration systems. Crafted with precision from high-quality copper, this reducer ensures exceptional durability and corrosion resistance, even in demanding environments. Its precisely threaded design guarantees a secure fit, preventing leaks and ensuring an airtight seal. The FTG Copper Fitting Reducer simplifies the installation process, allowing for smooth transitions between pipes of different sizes. Whether setting up a new cold room or making adjustments to an existing system, this reducer ensures a hassle-free installation, saving time and effort for technicians. Trust in the quality and dependability of our Copper Fitting Reducer for leak-free and efficient cold room operations, ensuring the integrity of your refrigeration system...', '{"Material": "High Purity Deoxidized Copper (Cu-DHP 99.9%)", "Standard": "ASME B16.22 / EN 1254-1", "Connection": "Sweat / Solder ODS", "Working Pressure": "Up to 45 bar (High Pressure Compatible)"}'::jsonb, TRUE, 5.0, 12, '/products/copper-fitting/fitting_reducer_ftg.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (33, 'Elbow', 'elbow-33', 5, 'Thilhara Genuine', 'TH-26', 'Introducing our Cold Room Accessories Copper Fitting Elbow – the key to secure and leak-free connections in refrigeration systems. Precision-crafted from high-quality copper, these elbows ensure exceptional durability and corrosion resistance. Their seamless design provides a tight seal, preventing refrigerant leaks and preserving the integrity of your cold room installation. Easy to install and compatible with various pipe sizes, these copper fitting elbows simplify the setup process, saving time and effort. Their robust construction and reliable performance make them indispensable components for ensuring the efficiency and longevity of your refrigeration system. Trust in our Copper Fitting Elbows for seamless connections, optimal refrigerant flow, and peace of mind in your cold storage solutions...', '{"Material": "High Purity Deoxidized Copper (Cu-DHP 99.9%)", "Standard": "ASME B16.22 / EN 1254-1", "Connection": "Sweat / Solder ODS", "Working Pressure": "Up to 45 bar (High Pressure Compatible)"}'::jsonb, TRUE, 5.0, 12, '/products/copper-fitting/elbow.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (34, 'Coupling with Roll-stop', 'coupling-with-roll-stop-34', 5, 'Thilhara Genuine', 'TH-19', 'Introducing our Cold Room Accessories Coupling with Roll-stop – the pinnacle of stability and seamless connections in cold room installations. Precision-engineered, this coupling ensures secure joints between cold room panels. Its innovative roll-stop feature prevents disengagement, providing added safety and durability. Crafted from high-quality materials, it withstands extreme temperatures, ensuring longevity in harsh environments. Easy to install, it simplifies construction, saving time and labor costs. The precision fit enhances insulation and maintains an airtight seal, ensuring efficient temperature control. Whether for industrial storage or commercial refrigeration, our Coupling with Roll-stop is essential for preserving cold room integrity, maximizing energy efficiency, and product preservation...', '{"Material": "High Purity Deoxidized Copper (Cu-DHP 99.9%)", "Standard": "ASME B16.22 / EN 1254-1", "Connection": "Sweat / Solder ODS", "Working Pressure": "Up to 45 bar (High Pressure Compatible)"}'::jsonb, TRUE, 5.0, 12, '/products/copper-fitting/coupling_with_roll-stop.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (35, 'Cap Tube End', 'cap-tube-end-35', 5, 'Thilhara Genuine', 'TH-10', 'Introducing our Air Condition Accessories Cap Tube End – the epitome of precision and reliability in refrigeration systems. These tube ends are meticulously crafted to ensure secure sealing and protection for capillary tubes, preventing leaks and contamination. Built from durable materials, they withstand high pressures and extreme temperatures, guaranteeing long-lasting performance in challenging environments. The easy-to-install design simplifies the connection process, saving valuable time during system assembly or repairs. Whether you''re a technician or a DIY enthusiast, our Cap Tube Ends offer a hassle-free solution for sealing and securing capillary tubes in air conditioning and refrigeration systems. Trust in the quality and durability of our accessories to maintain the integrity of your HVAC systems, ensuring efficient and reliable operation for years to come..', '{"Material": "High Purity Deoxidized Copper (Cu-DHP 99.9%)", "Standard": "ASME B16.22 / EN 1254-1", "Connection": "Sweat / Solder ODS", "Working Pressure": "Up to 45 bar (High Pressure Compatible)"}'::jsonb, TRUE, 5.0, 12, '/products/copper-fitting/cap_tube_end.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (36, 'SRS Suction Line Filter Drier', 'srs-suction-line-filter-drier-36', 6, 'Thilhara Genuine', 'TH-56', 'Introducing our SRS Suction Line Filter Drier – the essential solution for contaminant-free refrigerant flow in cold storage. Engineered for precision, this filter efficiently captures moisture, debris, and impurities, safeguarding compressors and vital components. Crafted from high-quality, corrosion-resistant materials, it ensures reliable performance in harsh conditions. The advanced filtration technology guarantees clean, dry refrigerant, promoting efficient heat exchange and extending your system''s life. Easy to install and maintain, it simplifies maintenance, saving time and effort for technicians. Trust in its effectiveness for uninterrupted cold room operations, preserving product freshness and maximizing your refrigeration system''s efficiency...', '{"Desiccant Core": "100% 3\u00c5 Molecular Sieve (Moisture & Acid Removal)", "Connections": "ODS Solder / SAE Flare", "Max Working Pressure": "45 bar (650 psi)", "Refrigerants": "All CFC, HCFC, and HFC Refrigerants"}'::jsonb, TRUE, 5.0, 12, '/products/filter-driers/srs_suction_line_filter_drier.jpg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (37, 'SRS Reversible Heat Pump Filter Drier', 'srs-reversible-heat-pump-filter-drier-37', 6, 'Thilhara Genuine', 'TH-55', 'Introducing our SRS Reversible Heat Pump Filter Drier – the ultimate solution for peak performance in heat pump systems. This precision-engineered drier ensures efficient filtration and moisture removal, protecting compressors and components from contaminants and excess humidity. Crafted with high-quality, durable, and corrosion-resistant materials, it guarantees reliability in heat pump applications. Its innovative design allows it to work effectively in both heating and cooling cycles, offering versatile protection year-round. Easy to install, it simplifies maintenance, saving time and effort for technicians. Trust in its efficiency to ensure uninterrupted heat pump operation, enhancing energy efficiency and prolonging your HVAC system''s life...', '{"Desiccant Core": "100% 3\u00c5 Molecular Sieve (Moisture & Acid Removal)", "Connections": "ODS Solder / SAE Flare", "Max Working Pressure": "45 bar (650 psi)", "Refrigerants": "All CFC, HCFC, and HFC Refrigerants"}'::jsonb, TRUE, 5.0, 12, '/products/filter-driers/srs_reversible_heat_pump_filter_drier.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (38, 'Oil Filter Drier', 'oil-filter-drier-38', 6, 'Thilhara Genuine', 'TH-43', 'Introducing our Oil Filter Drier – the ultimate solution for refrigeration system purity. Crafted with precision, it effectively filters out contaminants, moisture, and acids, ensuring equipment longevity. Made from high-quality materials, it withstands harsh conditions, preventing clogs and ensuring uninterrupted cooling. Easy to install and compact, it''s ideal for new installations and upgrades. Trust our Oil Filter Drier for clean, efficient, and long-lasting refrigeration systems...', '{"Desiccant Core": "100% 3\u00c5 Molecular Sieve (Moisture & Acid Removal)", "Connections": "ODS Solder / SAE Flare", "Max Working Pressure": "45 bar (650 psi)", "Refrigerants": "All CFC, HCFC, and HFC Refrigerants"}'::jsonb, TRUE, 5.0, 12, '/products/filter-driers/oil_filter_drier.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (39, 'Copper Spun Filter Drier (XS215)', 'copper-spun-filter-drier-xs215-39', 6, 'Thilhara Genuine', 'XS215', 'Introducing our Cold Room Accessories Copper Spun Filter Drier (XS215) – the foundation of refrigeration system longevity and efficiency. Precision-engineered, this filter drier boasts a robust copper spun shell, ensuring exceptional durability and corrosion resistance. Its advanced filtration design efficiently captures moisture, contaminants, and acids, protecting cold room equipment and refrigerants from damage. The XS215 Copper Spun Filter Drier prevents blockages and ice formation, ensuring seamless cooling performance. Easy to install, it integrates effortlessly into refrigeration lines, enhancing system reliability and extending your compressor''s lifespan. Compatible with various refrigerants and operating conditions, this filter drier is vital for maintaining optimal cold room functionality. Trust in XS215 for uninterrupted, efficient, and trouble-free refrigeration, safeguarding your investments and ensuring consistent temperature control for your valuable products...', '{"Desiccant Core": "100% 3\u00c5 Molecular Sieve (Moisture & Acid Removal)", "Connections": "ODS Solder / SAE Flare", "Max Working Pressure": "45 bar (650 psi)", "Refrigerants": "All CFC, HCFC, and HFC Refrigerants"}'::jsonb, TRUE, 5.0, 12, '/products/filter-driers/copper_spun_filter_drier_(xs215).png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (40, 'Copper Spun Filter Drier (XS215-big cap)', 'copper-spun-filter-drier-xs215-big-cap-40', 6, 'Thilhara Genuine', 'XS215-big cap', 'Introducing our Cold Room Accessories Copper Spun Filter Drier (XS215-big cap) – the pinnacle of filtration efficiency and durability for refrigeration systems. Engineered to perfection, this filter drier boasts a robust copper spun shell, offering exceptional corrosion resistance and longevity. Its advanced filtration technology captures moisture, contaminants, and acids, preserving the integrity of cold room equipment and refrigerants. The XS215-big cap Copper Spun Filter Drier prevents blockages, ice formation, and system breakdowns, ensuring uninterrupted cooling performance. Designed for easy installation, it fits seamlessly into refrigeration lines, enhancing system reliability and extending the compressor''s life. Suitable for various refrigerants and operating conditions, this filter drier is crucial for maintaining efficient and trouble-free cold room operations. It safeguards your investments, ensuring consistent, high-quality refrigeration...', '{"Desiccant Core": "100% 3\u00c5 Molecular Sieve (Moisture & Acid Removal)", "Connections": "ODS Solder / SAE Flare", "Max Working Pressure": "45 bar (650 psi)", "Refrigerants": "All CFC, HCFC, and HFC Refrigerants"}'::jsonb, TRUE, 5.0, 12, '/products/filter-driers/copper_spun_filter_drier_(xs215-big_cap).jpg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (41, 'Copper Spun Filter Drier (XS115)', 'copper-spun-filter-drier-xs115-41', 6, 'Thilhara Genuine', 'XS115', 'Introducing our Cold Room Accessories Copper Spun Filter Drier (XS115) – the ultimate solution for moisture and debris elimination in refrigeration systems. Precision-crafted with a high-grade copper spun shell, this drier ensures exceptional durability and resistance to corrosion. Its advanced filtration design effectively captures contaminants, safeguarding cold room equipment and refrigerants from damage. The XS115 Copper Spun Filter Drier guarantees moisture removal, preventing ice formation and maintaining optimal cooling efficiency. Easy to install and suitable for various refrigerants and operating conditions, this filter drier enhances system reliability and prolongs the life of your compressor. An indispensable accessory for efficient and long-lasting refrigeration systems, ensuring trouble-free performance in diverse cold room applications...', '{"Desiccant Core": "100% 3\u00c5 Molecular Sieve (Moisture & Acid Removal)", "Connections": "ODS Solder / SAE Flare", "Max Working Pressure": "45 bar (650 psi)", "Refrigerants": "All CFC, HCFC, and HFC Refrigerants"}'::jsonb, TRUE, 5.0, 12, '/products/filter-driers/copper_spun_filter_drier_(xs115).png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (42, 'Oil Separator', 'oil-separator-42', 7, 'Thilhara Genuine', 'TH-46', 'Introducing our Oil Separator – a vital component for efficient lubrication and optimal performance in refrigeration systems. Crafted with precision, it effectively removes oil from the refrigerant, preventing compressor damage and ensuring smooth operation. With high-quality materials, it withstands extreme temperatures and pressure in cold storage. Its innovative design guarantees efficient oil separation without compromising refrigeration. Easy to install and maintain, this separator enhances system efficiency, reduces wear on components, and extends equipment life. It prevents oil buildup, ensuring reliable and efficient cold room operations, maximizing system performance and longevity. Trust our Oil Separator for seamless oil management in refrigeration systems...', '{"Type": "Centrifugal Helical Separation", "Max Pressure": "45 bar", "Oil Return": "1/4 in Flare with Stainless Steel Float Valve", "Body Finish": "Epoxy Powder Paint Anti-Rust Finish"}'::jsonb, TRUE, 5.0, 12, '/products/oil-separators/oil_separator.jpg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (43, 'Oil Separator with Flange', 'oil-separator-with-flange-43', 7, 'Thilhara Genuine', 'TH-45', 'Introducing our Oil Separator with Flange – the solution for efficient oil management in refrigeration systems. Crafted with precision, it removes oil from the refrigerant, ensuring optimal lubrication for compressors. Engineered with a durable flange, it integrates easily into existing pipelines, simplifying installation. Its innovative design allows efficient oil separation without disrupting refrigeration. Withstand extreme temperatures and pressure fluctuations, enhancing efficiency, reducing wear on components, and extending equipment life. Trust our Oil Separator for seamless oil management, ensuring trouble-free operation in cold room systems...', '{"Type": "Centrifugal Helical Separation", "Max Pressure": "45 bar", "Oil Return": "1/4 in Flare with Stainless Steel Float Valve", "Body Finish": "Epoxy Powder Paint Anti-Rust Finish"}'::jsonb, TRUE, 5.0, 12, '/products/oil-separators/oil_separator_with_flange.jpg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (44, 'Mechanical Oil Level Regulator', 'mechanical-oil-level-regulator-44', 7, 'Thilhara Genuine', 'TH-41', 'Our Mechanical Oil Level Regulator is a reliable tool for your refrigeration systems. It maintains the right oil level, preventing damage and ensuring long-lasting efficiency. Made with durable materials, it works well in cold environments. It doesn''t need electricity, reducing complications. Technicians can easily adjust it to fit the system''s needs. Whether in freezers or coolers, it ensures smooth operations, protecting your equipment. Trust its accuracy and durability for top-notch performance...', '{"Type": "Centrifugal Helical Separation", "Max Pressure": "45 bar", "Oil Return": "1/4 in Flare with Stainless Steel Float Valve", "Body Finish": "Epoxy Powder Paint Anti-Rust Finish"}'::jsonb, TRUE, 5.0, 12, '/products/oil-separators/mechanical_oil_level_regulator.jpg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (45, 'Shaded Pole Motor', 'shaded-pole-motor-45', 8, 'Thilhara Genuine', 'TH-51', 'Introducing our Shaded Pole Motor – the essential component for reliable and energy-efficient air circulation in cold storage. Crafted with precision, this motor ensures consistent and quiet airflow in your cold room. Its shaded pole technology guarantees smooth operation and durability, withstanding varying temperatures and heavy use. Easy to install and maintain, this motor maintains optimal conditions, preventing temperature fluctuations and preserving the freshness of your stored products. Trust in its dependable performance to enhance product quality and extend the life of your refrigerated goods...', '{"Voltage": "220-240V / 50Hz", "Motor Protection": "IP44 / IP54 Thermal Protection", "Blades Material": "Aerodynamic Steel / Pressed Aluminum", "Bearing Type": "Maintenance-Free Sealed Ball Bearing"}'::jsonb, TRUE, 5.0, 12, '/products/axial-fan-motor/shaded_pole_motor.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (46, 'Axial Fan', 'axial-fan-46', 8, 'Thilhara Genuine', 'TH-7', 'Introducing our Cold Room Accessories Axial Fan – the pinnacle of efficient and uniform air circulation for your cold storage needs. Engineered with precision, this fan ensures optimal airflow, preventing temperature fluctuations and preserving the freshness of stored goods. Its high-performance, quiet motor creates a disturbance-free environment. Crafted from durable materials, this fan withstands harsh cold room conditions, guaranteeing exceptional reliability and longevity. Easy to install, it seamlessly integrates into your existing setup, enhancing air circulation and maintaining the desired temperature. Bid farewell to uneven cooling and welcome extended shelf life, thanks to our Cold Room Accessories Axial Fan. Enhance the efficiency of your cold storage, ensuring your products stay perfectly chilled and preserved..', '{"Voltage": "220-240V / 50Hz", "Motor Protection": "IP44 / IP54 Thermal Protection", "Blades Material": "Aerodynamic Steel / Pressed Aluminum", "Bearing Type": "Maintenance-Free Sealed Ball Bearing"}'::jsonb, TRUE, 5.0, 12, '/products/axial-fan-motor/axial_fan.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (47, 'Axial fan', 'axial-fan-47', 8, 'Thilhara Genuine', 'TH-4', 'Transform your refrigeration experience with our Refrigerator Accessories Axial Fan. Designed for superior performance, this fan ensures optimal airflow, preserving food freshness by preventing uneven cooling. Its sleek, compact design allows easy installation in any refrigerator model, operating silently to maintain a consistent temperature without disrupting your kitchen peace. Crafted from durable materials, it guarantees long-term reliability, eliminating food spoilage and extending shelf life. Plus, its energy-efficient operation not only saves on electricity bills but also makes it an eco-friendly choice. Upgrade your refrigerator today to enjoy enhanced airflow, quiet operation, and prolonged freshness with our Axial Fan..', '{"Voltage": "220-240V / 50Hz", "Motor Protection": "IP44 / IP54 Thermal Protection", "Blades Material": "Aerodynamic Steel / Pressed Aluminum", "Bearing Type": "Maintenance-Free Sealed Ball Bearing"}'::jsonb, TRUE, 5.0, 12, '/products/axial-fan-motor/axial_fan.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (48, 'Fan', 'fan-48', 8, 'Thilhara Genuine', 'TH-1', 'Upgrade your refrigerator''s performance with our advanced Refrigerator Accessories Fan. Engineered for optimal airflow, this fan ensures consistent cooling throughout your fridge, preserving freshness and extending shelf life. Its whisper-quiet operation won''t disrupt your kitchen ambiance, while its energy-efficient design helps you save on electricity bills. The easy-to-install fan promotes even air circulation, preventing hotspots and ensuring your food stays uniformly chilled. Equipped with durable materials, it guarantees long-lasting performance and reliability. Say goodbye to unpleasant odors and freezer burn as this fan eliminates stale air and maintains the ideal humidity level. Enhance your fridge''s efficiency and keep your groceries at their best with our Refrigerator Accessories Fan – the ultimate solution for a perfectly chilled, odor-free, and fresh food storage experience..', '{"Voltage": "220-240V / 50Hz", "Motor Protection": "IP44 / IP54 Thermal Protection", "Blades Material": "Aerodynamic Steel / Pressed Aluminum", "Bearing Type": "Maintenance-Free Sealed Ball Bearing"}'::jsonb, TRUE, 5.0, 12, '/products/axial-fan-motor/fan.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (49, 'Rotary Compressor', 'rotary-compressor-49', 9, 'Thilhara Genuine', 'TH-50', 'Introducing our Rotary Compressor – the pinnacle of reliable and energy-efficient refrigeration technology for cold storage. Engineered with precision, it ensures consistent cooling performance in demanding environments. Its smooth rotary motion guarantees quiet operation, making it ideal for noise-sensitive applications. Crafted from high-quality materials, it offers exceptional durability even under heavy loads. This advanced design maximizes energy efficiency, reducing operational costs and environmental impact. Easy to install and maintain, our Rotary Compressor is the top choice for commercial freezers, walk-in coolers, and industrial refrigeration units, ensuring your products are preserved in optimal conditions...', '{"Type": "Hermetic Scroll / Rotary", "Refrigerant": "R410A / R404A / R134a / R22", "Voltage": "220-240V / 1Ph / 50Hz (or 380V 3Ph)", "Application": "High / Medium / Low Back Pressure Commercial Cooling"}'::jsonb, TRUE, 5.0, 12, '/products/compressor/rotary_compressor.jpg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (50, 'Hermetic Compressor', 'hermetic-compressor-50', 9, 'Thilhara Genuine', 'TH-36', 'Introducing our Cold Room Accessories Hermetic Compressor – the heart of reliable refrigeration systems. Engineered for efficiency and durability, these hermetic compressors are designed to withstand the demands of cold storage environments. Their compact and sealed construction ensures minimal vibration and noise, delivering efficient cooling without disturbances. Crafted with high-quality materials, these compressors offer excellent performance, maintaining consistent temperatures within cold rooms. Whether for commercial freezers, walk-in coolers, or industrial refrigeration units, our hermetic compressors guarantee reliable operation, ensuring the freshness and longevity of stored products. With advanced technology and proven reliability, these compressors are the preferred choice for professionals seeking top-tier performance in cold room applications. Trust in our Hermetic Compressors for superior cooling efficiency and dependable operation in your refrigeration systems...', '{"Type": "Semi-Hermetic Reciprocating", "Refrigerant": "R410A / R404A / R134a / R22", "Voltage": "220-240V / 1Ph / 50Hz (or 380V 3Ph)", "Application": "High / Medium / Low Back Pressure Commercial Cooling"}'::jsonb, TRUE, 5.0, 12, '/products/compressor/hermetic_compressor.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (51, 'Copeland Scroll Compressor', 'copeland-scroll-compressor-51', 9, 'Copeland', 'TH-15', 'Introducing our Air Condition Accessories Copeland Scroll Compressor – the pinnacle of innovation and reliability in HVAC technology. This compressor stands out for its advanced design and superior efficiency, ensuring unmatched cooling performance for air conditioning systems. Engineered with precision, it utilizes scroll technology for smoother, quieter, and more energy-efficient operation compared to traditional compressors. Copeland Scroll Compressors deliver consistent cooling, even in demanding environments, ensuring desired temperatures are maintained. With outstanding reliability and durability, these compressors minimize downtime, reducing maintenance costs and enhancing HVAC system longevity. Suitable for residential and commercial use, our Copeland Scroll Compressor guarantees efficient, quiet, and reliable air conditioning, providing optimal comfort and energy savings for years to come...', '{"Type": "Hermetic Scroll / Rotary", "Refrigerant": "R410A / R404A / R134a / R22", "Voltage": "220-240V / 1Ph / 50Hz (or 380V 3Ph)", "Application": "High / Medium / Low Back Pressure Commercial Cooling"}'::jsonb, TRUE, 5.0, 12, '/products/compressor/copeland_scroll_compressor.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (52, 'Vacuum Pump (VP-1S)', 'vacuum-pump-vp-1s-52', 10, 'Thilhara Genuine', 'VP-1S', 'The Vacuum Pump (VP-1S) is a high-quality and efficient device designed to excel in a wide range of applications, from industrial processes to scientific research. Known for its robust performance, durability, and user-friendly features, this vacuum pump is an essential tool for professionals across various industries.', '{"Stages": "Single Stage Rotary Vane", "Flow Rate": "2.5 - 5.0 CFM", "Ultimate Vacuum": "15 - 25 Microns", "Oil Capacity": "250 ml - 350 ml"}'::jsonb, TRUE, 5.0, 12, '/products/vacum-pump/vacuum_pump_(vp-1s).png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (53, 'Vacuum Pump (VP-1A)', 'vacuum-pump-vp-1a-53', 10, 'Thilhara Genuine', 'VP-1A', 'The Vacuum Pump (VP-1A) is a high-performance, versatile, and robust device designed for a wide range of applications, from industrial processes to scientific research. This vacuum pump is engineered to provide exceptional suction power, reliability, and efficiency, making it an essential tool for professionals across various industries', '{"Stages": "Single Stage Rotary Vane", "Flow Rate": "2.5 - 5.0 CFM", "Ultimate Vacuum": "15 - 25 Microns", "Oil Capacity": "250 ml - 350 ml"}'::jsonb, TRUE, 5.0, 12, '/products/vacum-pump/vacuum_pump_(vp-1a).webp') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (54, 'V Series Rotlock Valves', 'v-series-rotlock-valves-54', 11, 'Thilhara Genuine', 'TH-66', 'The V Series Rotlock Valves represent the pinnacle of engineering excellence and precision in the world of industrial valves. These innovative valves are designed to offer superior performance, reliability, and efficiency in a wide range of industrial applications.', '{"Body Material": "Forged Brass / Cast Bronze", "Seat Seal": "PTFE Synthetic Polymer", "Max Working Pressure": "45 bar (650 psi)", "Connection": "ODF Solder / ODS / SAE Flare"}'::jsonb, TRUE, 5.0, 12, '/products/valves/v_series_rotlock_valves.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (55, 'Solenoid Valve', 'solenoid-valve-55', 11, 'Thilhara Genuine', 'TH-54', 'Introducing our Solenoid Valve – the epitome of precision and efficiency in HVAC systems. Designed for optimal performance, this valve provides precise control over refrigerant flow, ensuring seamless temperature regulation in air conditioning and refrigeration units. Crafted with high-quality materials, it offers durability and resistance to corrosion and wear in diverse environments. Its versatile design suits various applications, from commercial cooling to residential HVAC systems. The solenoid operation enables rapid responses, facilitating on-demand refrigerant flow adjustments. Easy to install and maintain, our Solenoid Valve ensures energy-efficient operation, reducing consumption and enhancing overall system performance. Trust in its reliability for precise refrigerant control, ensuring optimal comfort and cooling in your air conditioning installations...', '{"Body Material": "Forged Brass / Cast Bronze", "Seat Seal": "PTFE Synthetic Polymer", "Max Working Pressure": "45 bar (650 psi)", "Connection": "ODF Solder / ODS / SAE Flare"}'::jsonb, TRUE, 5.0, 12, '/products/valves/solenoid_valve.webp') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (56, 'Solenoid Valve (ODF)', 'solenoid-valve-odf-56', 11, 'Thilhara Genuine', 'ODF', 'Introducing our Solenoid Valve (ODF) – the pinnacle of precision and reliability in HVAC systems. This valve ensures seamless regulation of refrigerant flow, guaranteeing precise temperature control in air conditioning and refrigeration units. Crafted with high-quality materials, it offers durability, resisting corrosion and wear in demanding environments. Easy-to-install O-ring sealed ODF connections provide a secure, leak-free seal. Its reliable solenoid operation allows quick responses and on-demand refrigerant flow adjustments. Suitable for various applications, our Solenoid Valve (ODF) enhances system performance, reduces energy consumption, and ensures optimal comfort in commercial and residential HVAC systems. Trust in its reliability for precise refrigerant control and efficient operation...', '{"Body Material": "Forged Brass / Cast Bronze", "Seat Seal": "PTFE Synthetic Polymer", "Max Working Pressure": "45 bar (650 psi)", "Connection": "ODF Solder / ODS / SAE Flare"}'::jsonb, TRUE, 5.0, 12, '/products/valves/solenoid_valve_(odf).webp') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (57, 'Solenoid Valve (Flare)', 'solenoid-valve-flare-57', 11, 'Thilhara Genuine', 'Flare', 'Introducing our Solenoid Valve (Flare) – the pinnacle of precision control in HVAC systems. This valve ensures seamless regulation of refrigerant flow for precise temperature management in air conditioning and refrigeration units. Crafted for durability with high-quality materials, it resists corrosion and wear even in demanding environments. Easy-to-install flare connections provide a secure, leak-free seal. Its reliable solenoid operation allows quick responses and on-demand refrigerant flow adjustments. Suitable for various applications, our Solenoid Valve (Flare) enhances system performance, reduces energy consumption, and ensures optimal comfort in both commercial and residential HVAC systems. Trust in its reliability for precise refrigerant control and efficient operation...', '{"Body Material": "Forged Brass / Cast Bronze", "Seat Seal": "PTFE Synthetic Polymer", "Max Working Pressure": "45 bar (650 psi)", "Connection": "ODF Solder / ODS / SAE Flare"}'::jsonb, TRUE, 5.0, 12, '/products/valves/solenoid_valve_(flare).webp') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (58, 'Magnetic Check Valve', 'magnetic-check-valve-58', 11, 'Thilhara Genuine', 'TH-39', 'Introducing our Air Condition Accessories Magnetic Check Valve – the key to efficient and reliable refrigerant flow control in HVAC systems. Crafted with precision, this valve ensures unidirectional refrigerant flow, preventing backflow and optimizing system performance. Its innovative magnetic design allows for a swift response to changes in flow direction, guaranteeing seamless operation in both heating and cooling cycles. The durable construction and corrosion-resistant materials ensure longevity, even in demanding environments. Easy to install, the Magnetic Check Valve enhances system efficiency, reduces energy consumption, and minimizes wear on components. Whether for residential or commercial applications, this valve is a crucial component for maintaining consistent airflow, maximizing cooling efficiency, and prolonging the life of your HVAC system. Trust in its reliability for superior performance in your air conditioning and refrigeration systems...', '{"Body Material": "Forged Brass / Cast Bronze", "Seat Seal": "PTFE Synthetic Polymer", "Max Working Pressure": "45 bar (650 psi)", "Connection": "ODF Solder / ODS / SAE Flare"}'::jsonb, TRUE, 5.0, 12, '/products/valves/magnetic_check_valve.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (59, 'Ball Valve ODS', 'ball-valve-ods-59', 11, 'Thilhara Genuine', 'TH-8', 'Introducing our Air Condition Accessories Ball Valve ODS – a testament to precision control and durability for HVAC systems. Engineered with O-ring stem seals, this valve guarantees leak-free operation and seamless regulation of refrigerant flow. Its Outer Diameter Solder (ODS) design simplifies installation, saving valuable technician time. Crafted from high-grade materials, it withstands high pressures and extreme temperatures, ensuring long-lasting performance in diverse conditions. The smooth quarter-turn operation allows precise control over your air conditioning system, making it ideal for residential, commercial, or industrial use. Trust our high-quality valve to enhance your HVAC system''s performance, ensuring optimal cooling and heating capabilities for any space..', '{"Body Material": "Forged Brass / Cast Bronze", "Seat Seal": "PTFE Synthetic Polymer", "Max Working Pressure": "45 bar (650 psi)", "Connection": "ODF Solder / ODS / SAE Flare"}'::jsonb, TRUE, 5.0, 12, '/products/valves/ball_valve_ods.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (60, 'Access Valves', 'access-valves-60', 11, 'Thilhara Genuine', 'TH-5', 'Introducing our Air Condition Accessories Access Valves – the pinnacle of reliability and convenience for HVAC systems. These valves, designed for effortless refrigerant access, ensure seamless serviceability and maintenance. Crafted from premium materials, they endure high pressures and extreme temperatures, guaranteeing longevity in demanding conditions. With a user-friendly design, technicians can quickly and securely connect these valves, facilitating efficient charging or recovery of refrigerants. Whether it''s routine maintenance or system repairs, our Access Valves streamline the process, reducing downtime and enhancing operational efficiency. Their leak-free performance preserves cooling system integrity, preventing wastage and optimizing energy usage. Trust in our Air Condition Accessories Access Valves for superior functionality, simplifying HVAC servicing and ensuring peak system performance for years to come..', '{"Body Material": "Forged Brass / Cast Bronze", "Seat Seal": "PTFE Synthetic Polymer", "Max Working Pressure": "45 bar (650 psi)", "Connection": "ODF Solder / ODS / SAE Flare"}'::jsonb, TRUE, 5.0, 12, '/products/valves/access_valves.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (61, 'Ball Valve', 'ball-valve-61', 11, 'Thilhara Genuine', 'TH-3', 'Introducing our Air Condition Accessories Ball Valve – the pinnacle of precision and control for cooling systems. Crafted from top-quality materials, this valve enables seamless regulation of refrigerant flow, ensuring peak performance and energy efficiency. Its sturdy build can withstand high pressures and extreme temperatures, offering unmatched durability in various conditions. With smooth quarter-turn operation, adjustments are quick and precise, allowing effortless fine-tuning of your air conditioning system. Ideal for residential, commercial, or industrial use, our Ball Valve guarantees reliable, leak-free performance, enhancing your cooling equipment''s longevity. Its innovative design simplifies installation and maintenance, making it the top choice for HVAC professionals. Trust in our Air Condition Accessories Ball Valve for superior cooling control, maximizing efficiency and ensuring year-round comfort..', '{"Body Material": "Forged Brass / Cast Bronze", "Seat Seal": "PTFE Synthetic Polymer", "Max Working Pressure": "45 bar (650 psi)", "Connection": "ODF Solder / ODS / SAE Flare"}'::jsonb, TRUE, 5.0, 12, '/products/valves/ball_valve.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (62, 'HLP Series Pressure Controller (HLP830HLM)', 'hlp-series-pressure-controller-hlp830hlm-62', 12, 'Thilhara Genuine', 'HLP830HLM', 'Introducing our Air Condition Accessories HLP Series Pressure Controller (HLP830HLM) – the epitome of precision and reliability in HVAC systems. Engineered for optimal performance, this pressure controller ensures precise regulation of refrigerant pressures, guaranteeing efficient and stable operation of air conditioning units. With its advanced technology, the HLP830HLM offers real-time monitoring and adjustment, maintaining the ideal pressure levels for enhanced system efficiency. Crafted with durability in mind, it withstands high pressures and extreme conditions, ensuring long-lasting reliability. The user-friendly interface and intuitive controls simplify setup and adjustments, making it a preferred choice for HVAC professionals. Whether for residential or commercial applications, our HLP Series Pressure Controller is the key to maintaining consistent cooling performance, maximizing energy efficiency, and ensuring a comfortable indoor environment year-round...', '{"Range": "-0.5 to 30 bar", "Reset": "Auto Reset / Manual Reset", "Contact System": "SPDT Heavy Duty Microswitch", "Enclosure": "IP44 Protective Casing"}'::jsonb, TRUE, 5.0, 12, '/products/pressure-controls/hlp_series_pressure_controller_(hlp830hlm).jpg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (63, 'FC Series Sight Glass (FC04CS)', 'fc-series-sight-glass-fc04cs-63', 13, 'Thilhara Genuine', 'FC04CS', 'The FC Series Sight Glass (FC04CS) is a top-quality and versatile instrument that provides real-time visual insight into fluid systems, making it an essential component for professionals across various industries. This sight glass is known for its robust construction, precision, and reliability, allowing users to monitor and optimize fluid processes with confidence.', '{"Body": "Corrosion Resistant Brass", "Indicator": "Color Calibrated Moisture Indicator (Green: Dry, Yellow: Wet)", "Connections": "Male / Female Flare or ODS", "Max Pressure": "45 bar"}'::jsonb, TRUE, 5.0, 12, '/products/sight-glasses/fc_series_sight_glass_(fc04cs).png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (64, 'FC Series Sight Glass (FC04CF)', 'fc-series-sight-glass-fc04cf-64', 13, 'Thilhara Genuine', 'FC04CF', 'Introducing our Air Condition Accessories FC Series Sight Glass (FC04CF) – the vital component for monitoring refrigerant flow and system performance in HVAC installations. Crafted with precision, this sight glass offers a clear view of the refrigerant, enabling technicians to assess its condition and ensure proper levels. The FC04CF features a durable construction and a high-quality glass lens, guaranteeing longevity and resistance to pressure fluctuations. Its compact design makes installation seamless, fitting into refrigeration lines effortlessly. Equipped with moisture indicators, it aids in detecting potential issues like excess moisture in the system. Whether for residential cooling or commercial HVAC applications, the FC Series Sight Glass provides real-time insights, enabling efficient diagnostics and maintenance, ensuring your air conditioning system operates at peak efficiency...', '{"Body": "Corrosion Resistant Brass", "Indicator": "Color Calibrated Moisture Indicator (Green: Dry, Yellow: Wet)", "Connections": "Male / Female Flare or ODS", "Max Pressure": "45 bar"}'::jsonb, TRUE, 5.0, 12, '/products/sight-glasses/fc_series_sight_glass_(fc04cf).png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (65, 'Ms Series Start Capacitor', 'ms-series-start-capacitor-65', 14, 'Thilhara Genuine', 'TH-42', 'Introducing our MS Series Start Capacitor – a reliable choice for HVAC systems. These capacitors ensure smooth motor activation with their exceptional performance. Made from high-quality materials, they withstand high temperatures and heavy loads, extending motor lifespan. Easy to install and essential for efficient cooling, these capacitors optimize energy usage. Whether for homes or businesses, trust our MS Series for trouble-free startup and consistent cooling...', '{"Tolerance": "\u00b15%", "Voltage": "450V AC (50/60Hz)", "Safety Class": "P2 Flame Retardant Plastic / Aluminum Can", "Operating Temp": "-40\u00b0C to +85\u00b0C"}'::jsonb, TRUE, 5.0, 12, '/products/capacitors/ms_series_start_capacitor.jpg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (66, 'CBB Series Run Capacitor', 'cbb-series-run-capacitor-66', 14, 'Thilhara Genuine', 'TH-12', 'Introducing our Air Condition Accessories CBB Series Run Capacitor – the epitome of reliability and performance for HVAC systems. These capacitors provide a stable electrical charge, ensuring smooth operation and extended motor lifespan. Built with high-quality materials, they withstand high temperatures and heavy loads, offering consistent performance in demanding conditions. Their advanced design reduces energy consumption, enhancing system efficiency and lowering operational costs. Easy to install, they seamlessly integrate into your HVAC setup, boosting overall reliability and performance. Whether for residential or commercial use, our CBB Series Run Capacitors optimize system functionality, ensuring cool, comfortable environments with maximum energy efficiency. Upgrade your HVAC experience with these superior capacitors, providing dependable performance for years to come...', '{"Tolerance": "\u00b15%", "Voltage": "450V AC (50/60Hz)", "Safety Class": "P2 Flame Retardant Plastic / Aluminum Can", "Operating Temp": "-40\u00b0C to +85\u00b0C"}'::jsonb, TRUE, 5.0, 12, '/products/capacitors/cbb_series_run_capacitor.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (67, 'BC Series Run Capacitors', 'bc-series-run-capacitors-67', 14, 'Thilhara Genuine', 'TH-9', 'Enhance your HVAC system''s efficiency with our Air Condition Accessories BC Series Run Capacitors. These capacitors are engineered for superior performance, ensuring reliable operation of your air conditioner''s motor. Built to handle high temperatures and heavy loads, they provide a stable electrical charge, boosting the motor''s startup and running capabilities. Their durable construction and advanced materials guarantee longevity, even in demanding conditions. Easy to install, they seamlessly integrate into your system, enhancing its reliability and performance. Whether it''s a residential unit or a commercial HVAC system, our BC Series Run Capacitors optimize energy usage, reduce wear and tear, and extend equipment lifespan. Upgrade your air conditioning experience with these high-quality capacitors, ensuring a cool, comfortable environment with maximum energy efficiency..', '{"Tolerance": "\u00b15%", "Voltage": "450V AC (50/60Hz)", "Safety Class": "P2 Flame Retardant Plastic / Aluminum Can", "Operating Temp": "-40\u00b0C to +85\u00b0C"}'::jsonb, TRUE, 5.0, 12, '/products/capacitors/bc_series_run_capacitors.jpg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
