INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (73, 'Tubbing Tool Kit (FC275L)', 'tubbing-tool-kit-fc275l-73', 15, 'Thilhara Genuine', 'FC275L', 'Introducing our Tubing Tool Kit (FC275L) – the ultimate choice for HVAC professionals and enthusiasts seeking precision and efficiency. This kit features a high-quality tube cutter for smooth, accurate cuts, and a versatile flaring tool designed for perfect 45-degree flares on copper, aluminum, and brass tubes. These ergonomic tools ensure comfortable use and long-lasting performance, making them essential for leak-free connections in air conditioning and refrigeration systems. Whether you''re a seasoned technician or a DIY enthusiast, this kit provides the necessary tools for professional-grade tubing work, making it a valuable addition to your HVAC toolkit...', '{"Material": "Hardened Chrome Vanadium Alloy Steel", "Application": "HVAC & Refrigeration Pipework / Tubing", "Coating": "Corrosion Resistant Chrome Finish", "Packaging": "Heavy-Duty Blow Mold Case"}'::jsonb, TRUE, 5.0, 12, '/products/tools-and-equipment/tubbing_tool_kit_(fc275l).png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
