INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (75, 'Flaring Tools', 'flaring-tools-75', 15, 'Thilhara Genuine', 'TH-35', 'Introducing our Air Condition Accessories Flaring Tools – the epitome of precision tube installations in HVAC systems. Engineered for accuracy, these tools ensure flawless 45-degree flares on copper, aluminum, and brass tubing, facilitating seamless connections. Crafted from high-quality materials, they offer durability and longevity, making them reliable companions for professional technicians and DIY enthusiasts alike. The ergonomic design ensures comfort and ease of use, even in tight spaces, enhancing user efficiency. Suitable for various tube sizes, our flaring tools provide unmatched flexibility for different HVAC projects. Whether you''re installing air conditioning systems or working on refrigeration projects, these tools guarantee professional-grade flares, enabling secure and leak-free connections. Elevate your HVAC installations with our superior Flaring Tools, ensuring optimal performance and reliability in every connection...', '{"Material": "Hardened Chrome Vanadium Alloy Steel", "Application": "HVAC & Refrigeration Pipework / Tubing", "Coating": "Corrosion Resistant Chrome Finish", "Packaging": "Heavy-Duty Blow Mold Case"}'::jsonb, TRUE, 5.0, 12, '/products/tools-and-equipment/flaring_tools.png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (76, 'Flaring & Swaging Tool (FC195)', 'flaring-swaging-tool-fc195-76', 15, 'Thilhara Genuine', 'FC195', 'Introducing our Air Condition Accessories Flaring & Swaging Tool (FC195) – the pinnacle of precision and efficiency in HVAC tube preparations. Engineered for professionals, this versatile tool effortlessly creates flawless 45-degree flares and precise swages on copper, aluminum, and brass tubing. Its rugged construction and precision machining ensure consistent, leak-free connections every time, minimizing the risk of refrigerant leaks and system inefficiencies. The FC195 features a comfortable grip, providing precise control and ease of use, even in tight spaces. Suitable for various tube sizes, it offers unmatched flexibility for different HVAC projects. Whether you''re a seasoned technician or a DIY enthusiast, this tool guarantees professional-grade flaring and swaging, making it a vital addition to your toolkit for reliable and efficient tube connections in air conditioning and refrigeration systems...', '{"Material": "Hardened Chrome Vanadium Alloy Steel", "Application": "HVAC & Refrigeration Pipework / Tubing", "Coating": "Corrosion Resistant Chrome Finish", "Packaging": "Heavy-Duty Blow Mold Case"}'::jsonb, TRUE, 5.0, 12, '/products/tools-and-equipment/flaring_&_swaging_tool_(fc195).jpeg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (77, 'Flaring & Swaging Tool (FC193)', 'flaring-swaging-tool-fc193-77', 15, 'Thilhara Genuine', 'FC193', 'Introducing our Air Condition Accessories Flaring & Swaging Tool (FC193) – the ultimate tool for precise tube flaring and swaging in HVAC applications. Engineered for professionals, this versatile tool effortlessly creates perfect 45-degree flares and precise swages on copper, aluminum, and brass tubing. Its durable construction and precision machining ensure smooth and consistent results every time. The FC193 tool features a unique handle design for comfortable grip and control, making it easy to use even in tight spaces. Suitable for a range of tube sizes, it offers exceptional flexibility for various HVAC projects. Whether you''re a seasoned technician or a DIY enthusiast, this tool ensures professional-grade flaring and swaging, making it an essential addition to your HVAC toolkit for reliable and efficient tube connections...', '{"Material": "Hardened Chrome Vanadium Alloy Steel", "Application": "HVAC & Refrigeration Pipework / Tubing", "Coating": "Corrosion Resistant Chrome Finish", "Packaging": "Heavy-Duty Blow Mold Case"}'::jsonb, TRUE, 5.0, 12, '/products/tools-and-equipment/flaring_&_swaging_tool_(fc193).jpeg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (78, 'Fin Straightener (FC368180)', 'fin-straightener-fc368180-78', 15, 'Thilhara Genuine', 'FC368180', 'Introducing our Air Condition Accessories Fin Straightener (FC368180) – the pinnacle of precision and efficiency in HVAC maintenance. Meticulously crafted, this fin straightener is designed to restore bent or damaged fins on air conditioning and refrigeration coils. Its durable construction and precisely aligned teeth ensure safe and accurate straightening without causing harm to delicate fins. The FC368180 features an ergonomic grip, providing comfort and control, allowing technicians to navigate through tight spaces effortlessly. By straightening fins, this tool optimizes airflow, enhancing the system''s heat exchange efficiency and reducing energy consumption. It''s a must-have for maintaining consistent cooling performance, prolonging equipment lifespan, and achieving significant energy savings. Trust FC368180 for meticulous fin straightening, ensuring your HVAC systems operate at their peak efficiency...', '{"Material": "Hardened Chrome Vanadium Alloy Steel", "Application": "HVAC & Refrigeration Pipework / Tubing", "Coating": "Corrosion Resistant Chrome Finish", "Packaging": "Heavy-Duty Blow Mold Case"}'::jsonb, TRUE, 5.0, 12, '/products/tools-and-equipment/fin_straightener_(fc368180).png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
