INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (80, 'Fin Straightener (FC364M)', 'fin-straightener-fc364m-80', 15, 'Thilhara Genuine', 'FC364M', 'Introducing our Air Condition Accessories Fin Straightener (FC364M) – the ultimate tool for HVAC professionals to maintain optimal cooling efficiency. Crafted with precision, this fin straightener is designed to restore bent fins on air conditioning and refrigeration coils. Its sturdy metal construction and meticulously aligned teeth ensure accurate straightening without damaging delicate fins. The FC364M Straightener features a comfortable grip, allowing technicians to easily maneuver it through tight spaces. By straightening bent fins, airflow is restored, maximizing the efficiency of the cooling system and reducing energy consumption. This tool is essential for improving heat exchange and extending the lifespan of your air conditioner. Trust in FC364M to enhance your HVAC efficiency, ensuring consistent cooling performance and lower operational costs...', '{"Material": "Hardened Chrome Vanadium Alloy Steel", "Application": "HVAC & Refrigeration Pipework / Tubing", "Coating": "Corrosion Resistant Chrome Finish", "Packaging": "Heavy-Duty Blow Mold Case"}'::jsonb, TRUE, 5.0, 12, '/products/tools-and-equipment/fin_straightener_(fc364m).jpeg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (81, 'Cutter (PTC01)', 'cutter-ptc01-81', 15, 'Thilhara Genuine', 'PTC01', 'Introducing our Air Condition Accessories Tools and Equipment Cutter (PTC01) – a pinnacle of precision and versatility for HVAC professionals. Engineered for excellence, this cutter effortlessly handles various materials, including copper, aluminum, and plastic tubing. Its sharp, durable blade ensures clean and accurate cuts, streamlining installation processes. The ergonomic design provides a comfortable grip, reducing hand fatigue during extended use. Featuring a quick-change system, the PTC01 Cutter allows swift blade replacements, ensuring uninterrupted workflow on the job. Whether you''re working on air conditioning installations or refrigeration projects, this cutter offers exceptional performance and reliability. Its lightweight yet sturdy construction makes it an essential tool in your HVAC toolkit, guaranteeing smooth and professional cuts every time. Trust in the precision of PTC01 for superior results in your projects...', '{"Material": "Hardened Chrome Vanadium Alloy Steel", "Application": "HVAC & Refrigeration Pipework / Tubing", "Coating": "Corrosion Resistant Chrome Finish", "Packaging": "Heavy-Duty Blow Mold Case"}'::jsonb, TRUE, 5.0, 12, '/products/tools-and-equipment/cutter_(ptc01).webp') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (82, 'Cutter (FC312)', 'cutter-fc312-82', 15, 'Thilhara Genuine', 'FC312', 'Introducing our Air Condition Accessories Tools and Equipment Cutter (FC312) – the ultimate tool for precision and efficiency in HVAC installations. This professional-grade cutter is engineered to handle various materials effortlessly, including copper, aluminum pipes, and plastic tubing. Its sharp, hardened steel blade guarantees clean and accurate cuts, reducing installation time and effort. The ergonomic handle provides a comfortable grip, enhancing control and reducing hand fatigue during prolonged use. With a quick-change mechanism, the FC312 Cutter allows swift blade replacement, ensuring uninterrupted workflow. Whether you''re a seasoned HVAC technician or a DIY enthusiast, this cutter is your reliable partner for smooth and professional cuts in air conditioning and refrigeration projects. Upgrade your toolkit with FC312 for superior performance and exceptional results...', '{"Material": "Hardened Chrome Vanadium Alloy Steel", "Application": "HVAC & Refrigeration Pipework / Tubing", "Coating": "Corrosion Resistant Chrome Finish", "Packaging": "Heavy-Duty Blow Mold Case"}'::jsonb, TRUE, 5.0, 12, '/products/tools-and-equipment/cutter_(fc312).jpg') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
