INSERT INTO products (id, name, slug, category_id, brand, model, description, specs, in_stock, rating, reviews_count, image_url) VALUES (84, 'Cutter (FC174)', 'cutter-fc174-84', 15, 'Thilhara Genuine', 'FC174', 'Introducing our Air Condition Accessories Tools and Equipment Cutter (FC174) – the epitome of precision and efficiency in HVAC installations. This professional-grade cutter offers unmatched durability and versatility, making it ideal for various applications. Its sharp, hardened steel blade effortlessly slices through copper pipes, plastic tubing, and other materials, ensuring clean and precise cuts every time. The ergonomic handle provides a comfortable grip, reducing hand fatigue and enhancing control during operation. Equipped with a quick-change mechanism, the FC174 Cutter allows swift blade replacement, saving valuable time on the job. Whether you''re a seasoned HVAC technician or a DIY enthusiast, this cutter is a reliable companion for your air conditioning and refrigeration projects, delivering accurate cuts and professional results...', '{"Material": "Hardened Chrome Vanadium Alloy Steel", "Application": "HVAC & Refrigeration Pipework / Tubing", "Coating": "Corrosion Resistant Chrome Finish", "Packaging": "Heavy-Duty Blow Mold Case"}'::jsonb, TRUE, 5.0, 12, '/products/tools-and-equipment/cutter_(fc174).png') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, specs = EXCLUDED.specs, image_url = EXCLUDED.image_url;
